const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const headers = (item.json && item.json.headers) || {};
const ts = headers['x-lit-timestamp'];
const eventId = headers['x-lit-event-id'];
const signature = headers['x-lit-signature'];
if (!ts || !eventId || !signature) { throw new Error('Missing signing headers'); }
const body = (item.json && item.json.body) !== undefined ? item.json.body : {};
const rawBody = typeof body === 'string' ? body : JSON.stringify(body);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
const expected = 'v1=' + mac;
const a = Buffer.from(expected);
const b = Buffer.from(String(signature));
const matches = a.length === b.length && crypto.timingSafeEqual(a, b);
if (!matches) { throw new Error('Signature verification failed'); }
const nowSec = Math.floor(Date.now() / 1000);
if (Math.abs(nowSec - Number(ts)) > 300) { throw new Error('Signature timestamp outside tolerance'); }
return [{ json: { verified: true, eventId, timestamp: ts, body } }];

const item = $input.first().json;
const payload = (item.body && item.body.payload) ? item.body.payload : (item.body || {});
const deadLetterCount = Number(payload.deadLetterCount || payload.failedEvents || 0);
const pendingRetries = Number(payload.pendingRetries || 0);
const avgLatencyMs = Number(payload.avgLatencyMs || 150);
const activeWorkflowsCount = Number(payload.activeWorkflows || 10);
const checkedAt = new Date().toISOString();

let systemHealth = 'HEALTHY';
let requiresAlert = false;

if (deadLetterCount > 5 || avgLatencyMs > 5000) {
  systemHealth = 'CRITICAL';
  requiresAlert = true;
} else if (deadLetterCount > 0 || pendingRetries > 10) {
  systemHealth = 'DEGRADED';
  requiresAlert = true;
}

return [{
  json: {
    eventId: item.eventId,
    verified: item.verified,
    telemetry: {
      systemHealth,
      requiresAlert,
      deadLetterCount,
      pendingRetries,
      avgLatencyMs,
      activeWorkflowsCount,
      checkedAt,
      evaluatedBy: 'OPS-04 Automated Reliability Sentinel'
    }
  }
}];

const item = $input.first().json;
const t = item.telemetry;

const report = {
  status: t.systemHealth,
  headline: `Automation Platform Status: ${t.systemHealth}`,
  metrics: {
    deadLetterQueueSize: t.deadLetterCount,
    pendingRetries: t.pendingRetries,
    averageWebhookLatencyMs: t.avgLatencyMs
  },
  recommendedAction: t.systemHealth === 'CRITICAL'
    ? 'Drain dead-letter queue, inspect n8n container logs, restart lit_n8n'
    : (t.systemHealth === 'DEGRADED' ? 'Trigger automated retry runner /api/cron/automation-retry' : 'System operating within nominal thresholds'),
  timestamp: t.checkedAt
};

return [{
  json: {
    eventId: item.eventId,
    status: 'monitored',
    telemetry: t,
    report
  }
}];

const crypto = require('crypto');
const secret = $env.N8N_WEBHOOK_SECRET;
if (!secret) { throw new Error('N8N_WEBHOOK_SECRET is not set'); }
const item = $input.first();
const eventId = item.json.eventId;
const ts = String(Math.floor(Date.now() / 1000));
const payload = {
  eventId,
  status: item.json.status || 'monitored',
  detail: { telemetry: item.json.telemetry, report: item.json.report }
};
const rawBody = JSON.stringify(payload);
const mac = crypto.createHmac('sha256', secret).update(ts + '.' + eventId + '.' + rawBody).digest('hex');
return [{ json: { eventId, status: payload.status, rawBody, timestamp: ts, signature: 'v1=' + mac } }];
